package com.app.pegsolitaire.data.db

import androidx.room.Dao
import androidx.room.Insert

/**
 * Appends one solved play to the telemetry history (PGSA-06).
 *
 * This DAO is intentionally **write-only for now**: every projection, predicate and
 * aggregate over `play_session` is plan 12-06's job, and declaring a speculative read
 * here would be a second source of truth for numbers that plan has to own. Mirroring
 * [LevelResultDao]'s "this DAO stays a dumb store" note: no merge logic lives here.
 *
 * [Insert] rather than `@Upsert` is the correct verb — the primary key is autogenerated
 * and rows are append-only, so there is never an existing row to replace. Room compiles
 * and binds the statement, so no caller-supplied value can alter it (T-12-05).
 */
@Dao
interface PlaySessionDao {
    /** Appends one solved play; the autogenerated key is assigned by SQLite. */
    @Insert
    suspend fun insert(entity: PlaySessionEntity)
}
